function fillBottleDetails(code){const b=code.trim(),known=appState.bottles.includes(b);setBottleLineChecks(known?b:'');if(!known)return;$('#mapName').value=appState.bottleNames[b]||'';const p=$('#photoPreview');if(appState.bottleImages[b]){p.src=appState.bottleImages[b];p.hidden=false}else{p.removeAttribute('src');p.hidden=true}}
function previewSelectedBottle(code){const b=code.trim(),p=$('#selectedBottlePreview');if(!p)return;if(!appState.bottles.includes(b)){p.innerHTML='';return}p.innerHTML=`<div class="bottle-preview-row">${appState.bottleImages[b]?`<img src="${appState.bottleImages[b]}" alt="Foto flacone">`:'<span class="no-photo mini">Foto</span>'}<span><b>${esc(appState.bottleNames[b]||'Flacone')}</b><br>${esc(b)}</span></div>`}
async function saveBottleDetails(){try{if(!isCT())return toast('Operazione non autorizzata',true);const b=$('#mapBottle').value.trim(),n=$('#mapName').value.trim(),f=$('#mapPhoto').files[0],lineValues=[...document.querySelectorAll('[name="mapBottleLine"]:checked')].map(input=>input.value);if(!b||!n)return toast('Inserisci nome e codice',true);if(!lineValues.length)return toast('Scegli almeno una linea',true);toast(f?'Caricamento foto in corso…':'Salvataggio in corso…');appState.bottleNames[b]=n;if(f)appState.bottleImages[b]=await uploadBottlePhoto(f,b);if(!appState.bottles.includes(b))appState.bottles.push(b);appState.bottleLines[b]=lineValues;Object.values(appState.lines).filter(l=>l.bottle===b).forEach(l=>{l.bottleName=n;l.bottleImage=appState.bottleImages[b]||''});await save();const dialog=$('#bottleEditorDialog');if(dialog)dialog.close();render();toast(`Flacone salvato per ${lineValues.length===names.length?'tutte le linee':lineValues.join(', ')}`)}catch(e){toast(e.message||'Foto non salvata',true)}}
function loadBottleCard(code){const b=decodeURIComponent(code);if(!isCT())return toast('Operazione non autorizzata',true);showBottleEditDialog(b)}
async function selectBottleFromArchive(code){if(!isCT())return toast('Operazione non autorizzata',true);const b=decodeURIComponent(code),targetLine=$('#archiveTargetLine')?.value||selected;if(targetLine==='all'){appState.bottleLines[b]=[...names];await save();render();showBottleArchiveDialog();toast(`Codice ${b} disponibile su tutte le linee`);return}pendingArchiveBottle=b;pendingArchiveLine=targetLine;selected=targetLine;$('#bottleEditorDialog')?.close();render();showArchiveCodeQuantity(b,targetLine)}
async function deleteBottle(code){const b=decodeURIComponent(code);if(!isCT())return toast('Solo il CT può eliminare i codici',true);const activeLines=Object.values(appState.lines).filter(l=>String(l.bottle).trim()===b&&l.stage!=='idle'),active=activeLines.map(l=>l.name),name=appState.bottleNames[b]||'Flacone',photo=appState.bottleImages[b]||'';const warning=active.length?`\n\nÈ in uso sulle linee ${active.join(', ')}: le linee continueranno normalmente, ma il codice sparirà dall’archivio.`:'';if(!confirm(`Eliminare il codice ${b} dall’archivio?${warning}`))return;activeLines.forEach(l=>{l.bottleName=l.bottleName||name;l.bottleImage=l.bottleImage||photo});if(!active.length&&!previewActive()){const safe=b.replace(/[^a-zA-Z0-9_-]/g,'_');await db.storage.from('bottle-photos').remove([`${safe}.jpg`])}appState.bottles=appState.bottles.filter(x=>x!==b);delete appState.bottleColors[b];delete appState.bottleNames[b];delete appState.bottleImages[b];delete appState.bottleLines[b];await save();render();showBottleArchiveDialog();toast(`Codice ${b} ${previewActive()?'rimosso dalla simulazione':'eliminato dall’archivio'}`)}
function bottleArchive(){if(!isCT())return'';const codes=archiveCodes();return `<div class="archive-details"><div class="archive-dialog-heading"><strong>Archivio ${archiveScope==='line'?`linea ${selected}`:'di tutti i flaconi'} (${codes.length})</strong><small>Scegli usando codice e nome. La foto apparirà nel riepilogo.</small></div><div class="scope-actions"><button class="${archiveScope==='line'?'primary':''}" onclick="setArchiveScope('line')">Linea ${selected}</button><button class="${archiveScope==='all'?'primary':''}" onclick="setArchiveScope('all')">Tutti i flaconi</button></div><label class="field archive-target">Carica il codice sulla linea<select id="archiveTargetLine"><option value="${selected}">Linea ${selected}</option>${names.filter(name=>name!==selected).map(name=>`<option value="${name}">Linea ${name}</option>`).join('')}<option value="all">Tutte le linee</option></select></label><div class="archive-grid archive-grid-compact">${codes.length?codes.map(b=>`<div class="archive-card archive-card-compact"><b class="archive-code">${esc(b)}</b><span class="archive-name">${esc(appState.bottleNames[b]||'Flacone')}</span><div class="archive-actions"><button class="primary" onclick="selectBottleFromArchive('${encodeURIComponent(b)}')">Scegli</button><button onclick="loadBottleCard('${encodeURIComponent(b)}')">Modifica</button><button class="danger" onclick="deleteBottle('${encodeURIComponent(b)}')">Elimina</button></div></div>`).join(''):'<p class="muted">Nessun flacone associato a questa linea.</p>'}</div></div>`}
function bottleCreateForm(title='Crea nuovo codice'){return `<strong class="bottle-editor-title">${esc(title)}</strong><div class="grid bottle-editor-grid"><label class="field">Nome flacone<input id="mapName" placeholder="Es. Shampoo nero"></label><label class="field">Codice flacone<input id="mapBottle" list="bottles" placeholder="Inserisci il codice"></label><label class="field">Foto flacone · galleria o fotocamera<input id="mapPhoto" type="file" accept="image/*,.heic,.heif" onchange="previewBottlePhoto(this)"><small>Su iPhone scegli “Libreria foto” per cercare nella galleria.</small></label></div><fieldset class="bottle-line-picker"><legend>Linee sulle quali usare questo flacone</legend><label class="all-lines"><input id="mapAllLines" type="checkbox" onchange="toggleAllBottleLines(this.checked)"> Seleziona tutte le linee</label><div>${names.map(name=>`<label><input type="checkbox" name="mapBottleLine" value="${name}" ${name===selected?'checked':''}> ${name}</label>`).join('')}</div></fieldset><img id="photoPreview" class="photo-preview" hidden alt="Anteprima foto scelta"><div class="actions"><button class="primary" onclick="saveBottleDetails()">Salva flacone e linee</button></div>`}
function bottleEditorShell(content){const old=$('#bottleEditorDialog');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='bottleEditorDialog';dialog.className='line-quick-dialog bottle-editor-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button>${content}`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();return dialog}
function showBottleEditorMenu(){if(!isCT())return toast('Solo Amministratore, CT, Vice CT e Processista possono gestire i codici',true);const dialog=bottleEditorShell(`<strong>Gestione codici flacone</strong><p>Cosa vuoi fare?</p><div class="bottle-editor-actions"><button class="primary" id="createBottleChoice"><span>＋</span>Crea nuovo codice</button><button id="archiveBottleChoice"><span>▦</span>Apri archivio flaconi</button><button id="editBottleChoice">Modifica codice esistente</button></div>`);dialog.querySelector('#createBottleChoice').onclick=showBottleCreateDialog;dialog.querySelector('#archiveBottleChoice').onclick=showBottleArchiveDialog;dialog.querySelector('#editBottleChoice').onclick=showBottleEditPicker}
function showBottleArchiveDialog(){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Archivio flaconi</strong>${bottleArchive()}`);dialog.classList.add('bottle-archive-dialog')}
function showBottleCreateDialog(){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(bottleCreateForm());setBottleLineChecks('');setTimeout(()=>dialog.querySelector('#mapName')?.focus(),100)}
function showBottleEditPicker(){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(`<strong>Modifica codice esistente</strong><p>Inserisci o scegli il codice da modificare.</p><label class="field">Quale codice?<input id="editBottleCode" list="bottles" inputmode="text" placeholder="Es. P015442400"></label>${lists(appState.bottles)}<div class="actions"><button class="primary" id="openBottleEdit">Apri codice</button></div>`);dialog.querySelector('#openBottleEdit').onclick=()=>{const code=dialog.querySelector('#editBottleCode').value.trim();if(!appState.bottles.includes(code))return toast('Codice non trovato nell’archivio',true);dialog.close();showBottleEditDialog(code)};setTimeout(()=>dialog.querySelector('#editBottleCode')?.focus(),100)}
function showBottleEditDialog(code){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(bottleCreateForm(`Modifica codice ${code}`));$('#mapBottle').value=code;$('#mapBottle').readOnly=true;$('#mapName').value=appState.bottleNames[code]||'';setBottleLineChecks(code);const p=$('#photoPreview');if(appState.bottleImages[code]){p.src=appState.bottleImages[code];p.hidden=false}setTimeout(()=>dialog.querySelector('#mapName')?.focus(),100)}
function productionLineSelector(l){const available=Object.values(appState.lines).filter(line=>isCT()||canOperateLine(line));return `<label class="field production-line-choice">Scegli linea<select id="productionLineSelect">${available.map(line=>`<option value="${line.name}" ${line.name===l.name?'selected':''}>Linea ${line.name}${line.bottle?` · ${esc(appState.bottleNames[line.bottle]||line.bottleName||line.bottle)}`:''}</option>`).join('')}</select></label>`}
function productionBox(l){const selector=productionLineSelector(l),progress=l.productionTarget?`<div class="production-day-chip">Giornata produttiva · ${esc(productionDayLabel(l.productionDayKey||currentProductionDay()))}</div><h3>${Number(l.productionDone).toLocaleString('it-IT')} / ${Number(l.productionTarget).toLocaleString('it-IT')} ${unitLabel(l)}</h3><p>Assorbiti oggi <strong>${Number(l.productionDone).toLocaleString('it-IT')} ${unitLabel(l)}</strong> · Da assorbire ancora <strong>${productionRemaining(l).toLocaleString('it-IT')} ${unitLabel(l)}</strong></p>`:'<p>Quantità da assorbire non ancora impostata per la linea scelta.</p>',update=l.productionTarget&&isCT()?`<label class="field">Totale assorbito dall’inizio della giornata alle 06:00<input id="productionDone" type="number" min="0" max="${l.productionTarget}" value="${l.productionDone}"></label><small class="muted">Ogni turno sostituisce il valore precedente. Non inserire soltanto la quantità del turno.</small><div class="actions"><button class="primary" id="updateProduction">Aggiorna totale giornaliero</button></div>`:'',plan=isCT()?`<details class="production-plan"><summary>CT · modifica quantità da assorbire</summary><div class="actions"><select id="planUnit"><option value="pieces" ${l.productionUnit!=='ot'?'selected':''}>Pezzi</option><option value="ot" ${l.productionUnit==='ot'?'selected':''}>O.T.</option></select><input id="planTarget" type="number" min="1" value="${l.productionTarget||''}" placeholder="Quantità da assorbire"><button id="setProductionPlan">Salva quantità</button></div></details>`:'';return `<div class="notice production-overview" id="sectionProductionProgress"><strong>Avanzamento produzione</strong>${selector}${progress}${update}${plan}</div>`}
function productionQueue(l){const queue=Array.isArray(l.nextQueue)?l.nextQueue:[],cards=queue.length?queue.map((q,i)=>`<div class="queue-item"><span class="queue-number">${i+1}</span><div><strong>${esc(appState.bottleNames[q.bottle]||'Flacone')}</strong><small>Codice ${esc(q.bottle)} · ${Number(q.target).toLocaleString('it-IT')} ${q.unit==='ot'?'O.T.':'pezzi'}</small></div>${isCT()?`<button class="danger" data-queue-remove="${i}">Rimuovi</button>`:''}</div>`).join(''):'<p class="muted">Nessun codice successivo preparato.</p>',form=isCT()&&queue.length<10?`<div class="queue-form grid"><label class="field">Codice successivo<input id="queueBottle" list="bottles" placeholder="Cerca nell’archivio"></label><label class="field">Unità<select id="queueUnit"><option value="pieces">Pezzi</option><option value="ot">O.T.</option></select></label><label class="field">Quantità da assorbire<input id="queueTarget" type="number" min="1"></label></div><div class="actions"><button class="primary" id="queueAdd">Aggiungi alla programmazione</button></div>`:'';return `<details class="production-queue" id="sectionProductionQueue"><summary><strong>Codici successivi linea ${esc(l.name)}</strong>${queue.length?` <span>${queue.length} preparati</span>`:''}</summary><div class="queue-list">${cards}</div>${form}</details>`}
function handoverBox(l){if(!l.productionTarget)return'';return `<div class="notice"><strong>Passaggio consegne</strong>${l.handoverAt?`<p>Ultimo: ${esc(l.handoverShift)} · ${esc(l.handoverBy)} · ${showTime(l.handoverAt)}<br>${esc(l.handoverNote||'Nessuna nota')}</p>`:''}${canOperateLine(l)?`<div class="grid"><label class="field">Turno<select id="handoverShift"><option>Mattina</option><option>Pomeriggio</option><option>Notte</option></select></label><label class="field">Nota per il turno successivo<input id="handoverNote" placeholder="Situazione, problemi, materiale..."></label></div><div class="actions"><button id="saveHandover">Conferma passaggio consegne</button></div>`:''}</div>`}
function lineAssignment(l){const current=l.lineOwnerName?`Affidata a <strong>${esc(l.lineOwnerName)}</strong>`:'Nessuna persona assegnata';if(!canAssignLines())return `<div class="notice">${current}</div>`;return `<div class="notice"><strong>Affidamento linea</strong><p>${current}</p><div class="actions assignment-actions"><select id="lineOwner"><option value="">Nessuna persona</option>${operators.map(o=>`<option value="${o.id}" ${o.id===l.lineOwnerId?'selected':''}>${esc(o.display_name||'Utente')} · ${esc(roleLabels[o.role]||o.role)}</option>`).join('')}</select><button id="assignLine">Conferma assegnazione</button></div><small class="muted">La persona riceverà una notifica quando la linea viene aggiunta o rimossa.</small></div>`}
function correctionBox(l){return `<section class="dedicated-page-card" id="sectionLineCorrection"><div class="dedicated-page-heading"><small>Produzione Live</small><h2>Correggi Linea</h2><p>Scegli la linea e imposta manualmente la modalità corretta.</p></div><div class="notice"><strong>Correzione modalità linea</strong><label class="field stage-line-choice">Scegli la linea da correggere<select id="stageLineSelect">${names.map(name=>`<option value="${name}" ${name===l.name?'selected':''}>Linea ${name}${appState.lines[name].bottle?` · ${esc(appState.bottleNames[appState.lines[name].bottle]||appState.lines[name].bottleName||appState.lines[name].bottle)}`:''}</option>`).join('')}</select></label><div class="actions"><button class="green" onclick="if(confirm('Impostare In corso?'))act('set-stage',{stage:'running'})">In corso</button><button class="orange" onclick="if(confirm('Impostare Pre-raclage?'))act('set-stage',{stage:'pre'})">Pre-raclage</button><button class="yellow" onclick="if(confirm('Impostare Raclage?'))act('set-stage',{stage:'raclage'})">Raclage</button><button class="blue" onclick="if(confirm('Impostare Scarico?'))act('set-stage',{stage:'unload'})">Scarico</button><button class="red" onclick="if(confirm('Impostare Finito?'))act('set-stage',{stage:'finished'})">Finito</button></div></div></section>`}
function panel(l){const undo=l.stage!=='idle'&&l.undo?'<button onclick="if(confirm(\'Annullare davvero l’ultima azione?\'))act(\'undo\')">Annulla ultima azione</button>':'',close=isCT()&&l.stage!=='idle'?'<button class="danger" onclick="if(confirm(\'Chiudere definitivamente il ciclo della linea?\'))act(\'reset\')">Chiudi ciclo</button>':'',controls=undo||close?`<div class="actions cycle-controls">${undo}${close}</div>`:'',modes=isCT()?`<div class="notice"><strong>CT · correggi modalità linea</strong><label class="field stage-line-choice">Scegli la linea da correggere<select id="stageLineSelect">${names.map(name=>`<option value="${name}" ${name===l.name?'selected':''}>Linea ${name}${appState.lines[name].bottle?` · ${esc(appState.bottleNames[appState.lines[name].bottle]||appState.lines[name].bottleName||appState.lines[name].bottle)}`:''}</option>`).join('')}</select></label><div class="actions"><button class="green" onclick="if(confirm('Impostare In corso?'))act('set-stage',{stage:'running'})">In corso</button><button class="orange" onclick="if(confirm('Impostare Pre-raclage?'))act('set-stage',{stage:'pre'})">Pre-raclage</button><button class="yellow" onclick="if(confirm('Impostare Raclage?'))act('set-stage',{stage:'raclage'})">Raclage</button><button class="blue" onclick="if(confirm('Impostare Scarico?'))act('set-stage',{stage:'unload'})">Scarico</button><button class="red" onclick="if(confirm('Impostare Finito?'))act('set-stage',{stage:'finished'})">Finito</button></div></div>`:'';const bottleButtons=isCT()?'<div class="bottle-toolbar"><button class="bottle-add-button" type="button" onclick="showBottleEditorMenu()" aria-label="Crea, cerca o modifica codice">＋</button></div>':'',h=`${bottleButtons?`<div class="line-panel-title line-panel-tools-only">${bottleButtons}</div>`:''}<span class="status">${esc(labels[l.stage])}</span>${lineAssignment(l)}${controls}${modes}`,info=`${productionBox(l)}${productionQueue(l)}`;
 if(l.stage==='idle')return h+productionBox(l)+(isCT()?productionQueue(l):'<p>In attesa che il CT assegni il codice alla linea.</p>');
 if(l.stage==='running')return h+info;
 if(l.stage==='pre')return h+info;
 if(l.stage==='progress'&&l.remainingPieces===null){const extra=l.extraRequested?(!l.extraAssignedTo?'<button id="takeExtra">Prendo in carico big bag aggiuntivo</button>':`<p>Big bag aggiuntivo in carico a <strong>${esc(l.extraAssignedTo)}</strong>${l.extraLoaded?' · caricato':''}</p>${!l.extraLoaded&&(l.extraAssignedTo===actor()||isAdmin())?'<button id="extraLoaded">Conferma big bag caricato</button>':''}`):'';return h+info+(extra?`<div class="notice"><strong>Big bag aggiuntivo</strong>${extra}</div>`:'')}
 if(l.stage==='waiting-raclage'){const available=l.bag1+l.bag2,remainingResult=`<div class="notice flow-step remaining-result"><strong>Rimanenza comunicata dall’operatore</strong><h3>${available} big bag disponibil${available===1?'e':'i'}</h3><p>Big bag 1: <b>${l.bag1?'Pieno':'Vuoto'}</b> · Big bag 2: <b>${l.bag2?'Pieno':'Vuoto'}</b><br>Vasca: <b>${vatLabel(l.vatLevel)}</b></p>${isCT()?'<p>Chiama il raclage dal riquadro della linea.</p>':'<p>In attesa della chiamata raclage del CT.</p>'}</div>`;return h+remainingResult+info}
 if(l.stage==='raclage')return h+info;
 if(l.stage==='progress'&&l.remainingPieces===-1)return h+info;
 if(l.stage==='waiting-ct')return h+info+`<div class="notice flow-step remaining-result"><strong>Rimanenza dopo raclage</strong><h3>Vasca ${vatLabel(l.raclageVatLevel)}</h3><p><b>${Number(l.remainingPieces).toLocaleString('it-IT')} pezzi avanzati</b><br>In attesa della verifica del CT.</p>${isCT()?'<div class="actions"><button class="primary" id="ctOk">CT: OK</button><button id="ctNo">CT: Non OK</button></div>':''}</div>`;
 if(l.stage==='raclage-ok')return h+info+`<div class="notice flow-step"><strong>Raclage completato</strong><p>Rimangono <b>${Math.max(0,Number(l.remainingPieces||0)).toLocaleString('it-IT')} pezzi</b>. Il prossimo passaggio è soltanto lo scarico.</p><div class="actions"><button class="primary" id="startUnload">Avvia scarico linea</button></div></div>`;
 if(l.stage==='unload')return h+info;
 if(l.stage==='finished'){const next=l.nextQueue?.[0];return h+info+`<p><strong>Linea pulita confermata.</strong></p>${next&&isCT()?`<div class="notice queue-next"><strong>Primo codice già preparato</strong><h3>${esc(appState.bottleNames[next.bottle]||'Flacone')} · ${esc(next.bottle)}</h3><p>${Number(next.target).toLocaleString('it-IT')} ${next.unit==='ot'?'O.T.':'pezzi'} da assorbire</p><button class="primary" id="queueStartNext">Avvia prossimo codice in coda</button></div>`:''}<details><summary>Oppure scegli manualmente un altro codice</summary><div class="grid"><label class="field">Codice successivo<input id="nextBottle" list="bottles"></label><label class="field">Unità<select id="nextUnit"><option value="pieces">Pezzi</option><option value="ot">O.T.</option></select></label><label class="field">Quantità da assorbire<input id="nextTarget" type="number" min="1"></label></div>${lists()}<div class="actions"><button class="primary" id="nextLoad">Conferma inizio carico</button></div></details>`}
 return h+info+'<p>Carico in corso.</p>'}
function bind(){const on=(id,fn)=>{const e=$('#'+id);if(e)e.onclick=fn};on('assignLine',()=>act('assign-line',{ownerId:$('#lineOwner').value}));on('setProductionPlan',()=>act('set-production-plan',{unit:$('#planUnit').value,target:$('#planTarget').value,note:''}));on('updateProduction',()=>act('update-production',{value:$('#productionDone').value}));on('saveHandover',()=>act('handover',{shift:$('#handoverShift').value,note:$('#handoverNote').value}));on('queueAdd',()=>act('queue-add',{bottle:$('#queueBottle').value,unit:$('#queueUnit').value,target:$('#queueTarget').value,note:''}));document.querySelectorAll('[data-queue-remove]').forEach(button=>button.onclick=()=>act('queue-remove',{index:button.dataset.queueRemove}));on('queueStartNext',confirmQueuedStartCode);on('saveColor',async()=>{const b=$('#mapBottle').value.trim(),c=$('#mapColor').value.trim();if(!b||!c)return toast('Inserisci codice e colore',true);appState.bottleColors[b]=c;if(!appState.bottles.includes(b))appState.bottles.push(b);await save();render();toast('Associazione salvata')});on('savePre',()=>act('save-pre',{bottle:$('#bottle').value,prePieces:$('#prePieces').value,extraRequested:$('#extra').value==='yes'}));on('takePre',()=>act('take-pre'));on('takeExtra',()=>act('take-extra'));on('extraLoaded',()=>act('extra-loaded'));on('submitPre',()=>act('submit-pre',{bag1:$('#bag1').value,bag2:$('#bag2').value}));on('callRaclage',()=>act('call-raclage'));on('takeRaclage',()=>act('take-raclage'));on('submitRaclage',()=>act('submit-raclage',{remainingPieces:$('#remaining').value}));on('ctOk',()=>act('ct-decision',{decision:'ok'}));on('ctNo',()=>act('ct-decision',{decision:'no'}));on('startUnload',()=>act('start-unload'));on('takeUnload',()=>act('take-unload'));on('confirmClean',()=>$('#cleanCheck').checked?act('confirm-clean'):toast('Conferma la verifica della linea',true));on('nextLoad',confirmNextLoad);on('reset',()=>act('reset'));const stageChoice=$('#stageLineSelect');if(stageChoice)stageChoice.onchange=()=>{const detail=stageChoice.closest('#lineDetailDialog');selected=stageChoice.value;if(detail)detail.close();render();if(detail)setTimeout(()=>showLineDetailsDialog(selected),30)}}
function showCodeStartConfirmation(type,data,editTarget){if(!isCT())return toast('Operazione non autorizzata',true);const bottle=String(data.bottle||'').trim(),target=Math.max(0,Number(data.target||0)),unit=data.unit==='ot'?'ot':'pieces';if(!bottle||!appState.bottles.includes(bottle))return toast('Scegli un flacone dall’archivio',true);if(!target)return toast('Inserisci la quantità da assorbire',true);const old=$('#codeStartDialog');if(old)old.remove();const name=appState.bottleNames[bottle]||'Flacone',photo=appState.bottleImages[bottle]||'',dialog=document.createElement('dialog');dialog.id='codeStartDialog';dialog.className='line-quick-dialog code-start-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button><strong class="bottle-editor-title">Vuoi avviare questo codice?</strong><p>Controlla il riepilogo prima di confermare.</p><div class="code-start-review">${photo?`<img src="${photo}" alt="Foto ${esc(name)}">`:''}<div><small>Linea</small><b>${esc(selected)}</b><small>Nome flacone</small><b>${esc(name)}</b><small>Codice</small><b>${esc(bottle)}</b><small>Quantità da assorbire</small><b>${target.toLocaleString('it-IT')} ${unit==='ot'?'O.T.':'pezzi'}</b></div></div><div class="line-quick-actions"><button class="primary" id="confirmCodeStart">Conferma e avvia</button><button id="editCodeStart">Modifica i dati</button></div>`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.querySelector('#confirmCodeStart').onclick=async()=>{const actionData=type==='queue-start-next'?{}:type==='next-load'?{nextBottle:bottle,target,unit,note:data.note||''}:{...data,bottle,target,unit};if(await act(type,actionData))dialog.close()};dialog.querySelector('#editCodeStart').onclick=()=>{dialog.close();setTimeout(()=>{if(typeof editTarget==='function')editTarget();else{const targetElement=$(editTarget);targetElement?.scrollIntoView({behavior:'smooth',block:'center'});if(targetElement?.matches('input,select'))targetElement.focus()}},80)};dialog.onclose=()=>dialog.remove();dialog.showModal()}
function showArchiveCodeQuantity(bottle,line=selected,values={}){if(!isCT())return toast('Operazione non autorizzata',true);selected=line;const l=appState.lines[line],type=l.stage==='idle'?'start-code':l.stage==='finished'?'next-load':'change-code',old=$('#archiveQuantityDialog');if(old)old.remove();const name=appState.bottleNames[bottle]||'Flacone',photo=appState.bottleImages[bottle]||'',dialog=document.createElement('dialog');dialog.id='archiveQuantityDialog';dialog.className='line-quick-dialog code-start-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button><strong class="bottle-editor-title">Codice scelto · Linea ${esc(line)}</strong><div class="archive-code-review">${photo?`<img src="${photo}" alt="Foto ${esc(name)}">`:'<span class="no-photo">Foto non salvata</span>'}<div><small>Codice</small><b>${esc(bottle)}</b><small>Nome flacone</small><b>${esc(name)}</b></div></div><div class="grid"><label class="field">Unità produzione<select id="archiveStartUnit"><option value="pieces" ${(values.unit||l.productionUnit)!=='ot'?'selected':''}>Pezzi</option><option value="ot" ${(values.unit||l.productionUnit)==='ot'?'selected':''}>O.T.</option></select></label><label class="field">Quantità da assorbire<input id="archiveStartTarget" type="number" min="1" inputmode="numeric" value="${esc(values.target||'')}" placeholder="Inserisci quantità"></label></div><div class="line-quick-actions"><button class="primary" id="reviewArchiveStart">Conferma la scelta</button><button id="changeArchiveBottle">Scegli un altro codice</button></div>`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.querySelector('#changeArchiveBottle').onclick=()=>{dialog.close();showBottleArchiveDialog()};dialog.querySelector('#reviewArchiveStart').onclick=()=>{const data={bottle,unit:dialog.querySelector('#archiveStartUnit').value,target:dialog.querySelector('#archiveStartTarget').value,note:''};if(!Number(data.target))return toast('Inserisci la quantità da assorbire',true);dialog.close();showCodeStartConfirmation(type,data,()=>showArchiveCodeQuantity(bottle,line,data))};dialog.onclose=()=>dialog.remove();dialog.showModal();setTimeout(()=>dialog.querySelector('#archiveStartTarget')?.focus(),80)}
function confirmQueuedStartCode(){const next=appState.lines[selected]?.nextQueue?.[0];if(!next)return toast('Nessun codice successivo preparato',true);showCodeStartConfirmation('queue-start-next',{bottle:next.bottle,unit:next.unit,target:next.target,note:next.note},'.production-queue')}
function confirmNextLoad(){showCodeStartConfirmation('next-load',{bottle:$('#nextBottle')?.value,unit:$('#nextUnit')?.value,target:$('#nextTarget')?.value,note:''},'#nextTarget')}
function goToBottleArea(mode){if(mode==='create')return showBottleCreateDialog();if(mode==='archive')return showBottleArchiveDialog();if(canUseCtBottomNav()&&['queue','production'].includes(mode)){document.querySelectorAll('#lineActionMenu,#lineDetailDialog').forEach(dialog=>{if(dialog.open)dialog.close()});ctBottomNavActive=mode;render();return}if(mode==='queue'){const queue=$('#panel .production-queue');if(!queue)return toast('Programmazione non disponibile',true);queue.open=true;queue.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>$('#queueBottle')?.focus(),350);return}if(mode==='production'){const plan=$('#panel .production-plan');if(!plan)return toast('Avvia prima un codice sulla linea',true);plan.open=true;plan.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>$('#planTarget')?.focus(),350)}}
function lineActionContent(l){const remaining=productionRemaining(l).toLocaleString('it-IT'),unit=unitLabel(l);if(l.stage==='idle')return `<p>Nessun codice in corso.</p><div class="line-quick-actions"><button class="primary" data-go="archive">Crea o carica un codice</button><button data-go="queue">Prepara codici successivi</button></div>`;if(l.stage==='running')return `<p><strong>Avviare il pre-raclage?</strong></p><label class="field">Quantità flaconi mancanti<input id="quickPrePieces" type="number" min="0" value="${Number(l.prePieces)||10000}"></label><div class="line-quick-actions"><button class="primary" data-action="save-pre">Conferma pre-raclage</button><button data-go="production">Modifica quantità da assorbire</button></div><small>Mancano ancora ${remaining} ${unit} da assorbire.</small>`;if(l.stage==='pre'||(l.stage==='progress'&&l.remainingPieces===null))return `<p><strong>Pre-raclage in corso</strong></p><p>Richiesta effettuata a ${Number(l.prePieces).toLocaleString('it-IT')} flaconi mancanti. Attendi la risposta dell’operatore.</p>`;if(l.stage==='waiting-raclage'){const bags=Number(l.bag1)+Number(l.bag2);return `<p><strong>Chiamare il raclage?</strong></p><div class="quick-result"><b>${bags} big bag disponibil${bags===1?'e':'i'}</b><small>BB1 ${l.bag1?'pieno':'vuoto'} · BB2 ${l.bag2?'pieno':'vuoto'} · Vasca ${vatLabel(l.vatLevel).toLowerCase()} · richiesta a ${Number(l.prePieces).toLocaleString('it-IT')}</small></div><div class="line-quick-actions"><button class="primary" data-action="call-raclage">Conferma raclage</button></div>`}if(l.stage==='raclage'||(l.stage==='progress'&&l.remainingPieces===-1))return `<p><strong>Raclage in corso</strong></p><p>L’operatore deve verificare e dichiarare quanti pezzi sono avanzati.</p><div class="line-quick-actions"><button data-go="details">Apri verifica</button></div>`;if(l.stage==='waiting-ct')return `<p><strong>Raclage: quanto è rimasto?</strong></p><div class="quick-result"><b>${Number(l.remainingPieces).toLocaleString('it-IT')} pezzi avanzati</b><small>Conferma se la quantità è corretta.</small></div><div class="line-quick-actions"><button class="primary" data-action="ct-ok">CT: OK</button><button data-action="ct-no">CT: Non OK</button></div>`;if(l.stage==='raclage-ok')return `<p><strong>Si può avviare lo scarico?</strong></p><p>Raclage approvato · ${Math.max(0,Number(l.remainingPieces||0)).toLocaleString('it-IT')} pezzi avanzati.</p><div class="line-quick-actions"><button class="primary" data-action="start-unload">Sì, avvia scarico</button></div>`;if(l.stage==='unload')return `<p><strong>Scarico linea in corso</strong></p><div class="quick-result"><b>Mancano ${remaining} ${unit}</b><small>da assorbire sulla produzione programmata</small></div><div class="line-quick-actions"><button data-go="details">Verifica pulizia linea</button></div>`;if(l.stage==='finished'){const queued=l.nextQueue?.length||0;return `<p><strong>Linea pulita e produzione finita</strong></p><div class="quick-result"><b>${queued?`${queued} codici successivi preparati`:'Nessun codice successivo preparato'}</b><small>${queued?'Apri il primo codice già programmato.':'Scegli il nuovo flacone dall’archivio della linea.'}</small></div><div class="line-quick-actions"><button class="primary" data-go="${queued?'details':'archive'}">${queued?'Avvia codice già preparato':'Scegli dall’archivio flaconi'}</button></div>`}return `<p>Stato: ${esc(labels[l.stage]||l.stage)}</p>`}
function showLineDetailsDialog(line){selected=line;const old=$('#lineDetailDialog');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='lineDetailDialog';dialog.className='line-quick-dialog line-detail-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button><div class="line-detail-heading"><small>Scheda completa</small><strong>Linea ${esc(line)}</strong></div><div class="line-detail-content">${panel(appState.lines[line])}</div>`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();bind();bindProductionSelector()}
function showLineActionMenu(line){selected=line;render();loadHistory();const l=appState.lines[line],old=$('#lineActionMenu');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='lineActionMenu';dialog.className='line-quick-dialog line-action-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button><strong>Linea ${esc(line)}</strong>${lineActionContent(l)}`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>{const mode=button.dataset.go;dialog.close();if(mode==='details')setTimeout(()=>showLineDetailsDialog(line),30);else goToBottleArea(mode)});dialog.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.action,prePieces=dialog.querySelector('#quickPrePieces')?.value||l.prePieces;dialog.close();if(action==='save-pre')act('save-pre',{bottle:l.bottle,prePieces,extraRequested:false});if(action==='call-raclage')act('call-raclage');if(action==='ct-ok')act('ct-decision',{decision:'ok'});if(action==='ct-no')act('ct-decision',{decision:'no'});if(action==='start-unload')act('start-unload')});dialog.onclose=()=>dialog.remove();dialog.showModal()}
function cardAbsorption(l){if(['pre','waiting-raclage','raclage'].includes(l.stage)||(l.stage==='progress'&&(l.remainingPieces===null||l.remainingPieces===-1)))return{value:Number(l.prePieces||0),unit:'pezzi'};if(['waiting-ct','raclage-ok','unload','finished'].includes(l.stage)&&Number(l.remainingPieces)>=0)return{value:Number(l.remainingPieces||0),unit:'pezzi'};return{value:l.productionTarget?productionRemaining(l):0,unit:unitLabel(l)}}
function toggleTaskBag(button){const input=button.closest('dialog').querySelector('#'+button.dataset.input),full=input.value!=='1';input.value=full?'1':'0';button.classList.toggle('is-full',full);button.classList.toggle('is-empty',!full);button.setAttribute('aria-pressed',String(full));button.setAttribute('aria-label',`${button.dataset.label}: ${full?'Pieno':'Vuoto'}. Tocca per cambiare.`);button.querySelector('.bb-state-label').textContent=full?'Pieno':'Vuoto'}
function raclageEstimate(level){return{full:3000,half:1500,low:500,empty:0}[level]??0}
function updateRaclageEstimate(dialog,level){const output=dialog.querySelector('#taskRaclageEstimate');if(output)output.textContent=`Quantità proposta: ${raclageEstimate(level).toLocaleString('it-IT')} flaconi`}
function toggleTaskVat(button){const dialog=button.closest('dialog'),input=dialog.querySelector('#'+button.dataset.input),levels=button.dataset.allowEmpty==='true'?['full','half','low','empty']:['full','half','low'],next=levels[(levels.indexOf(input.value)+1)%levels.length];input.value=next;button.className=`bb-vat vat-selector is-${next}`;button.setAttribute('aria-label',`Vasca ${vatLabel(next)}. Tocca per cambiare.`);button.querySelector('.vat-state-label').textContent=vatLabel(next);if(button.dataset.allowEmpty==='true')updateRaclageEstimate(dialog,next)}
function taskDialogContent(line,kind){const l=appState.lines[line],extra=l.extraRequested?`<p class="task-extra">Big bag aggiuntivo: <strong>${l.extraLoaded?'caricato':'ancora da caricare'}</strong></p>`:'';if(kind==='pre')return `<strong>Linea ${esc(line)} · Pre-raclage</strong><p>La vasca parte da Piena. Tocca i big bag o la vasca solo se devi modificare la situazione.</p><div class="bb-station" aria-label="Stazione vibrante linea ${esc(line)}"><div class="bb-pair"><button type="button" class="bb-selector is-full" data-input="taskBag1" data-label="Big bag 1" aria-pressed="true" aria-label="Big bag 1: Pieno. Tocca per cambiare." onclick="toggleTaskBag(this)"><span class="bb-sack"><span class="bb-fill"></span></span><strong>Big bag 1</strong><span class="bb-state-label">Pieno</span></button><button type="button" class="bb-selector is-full" data-input="taskBag2" data-label="Big bag 2" aria-pressed="true" aria-label="Big bag 2: Pieno. Tocca per cambiare." onclick="toggleTaskBag(this)"><span class="bb-sack"><span class="bb-fill"></span></span><strong>Big bag 2</strong><span class="bb-state-label">Pieno</span></button></div><div class="bb-connections"><span></span><span></span></div><button type="button" class="bb-vat vat-selector is-full" data-input="taskVat" aria-label="Vasca Piena. Tocca per cambiare." onclick="toggleTaskVat(this)"><span class="vat-fill"></span><strong>VASCA</strong><small>Linea ${esc(line)}</small><span class="vat-state-label">Piena</span></button></div><input id="taskBag1" type="hidden" value="1"><input id="taskBag2" type="hidden" value="1"><input id="taskVat" type="hidden" value="full">${extra}<button class="primary task-confirm" id="taskConfirm">Conferma e invia al CT</button>`;if(kind==='raclage')return `<strong>Linea ${esc(line)} · Raclage</strong><p>La vasca parte da Piena. Toccala solo se devi passare a Metà, Quasi vuota o Vuota.</p><div class="bb-station raclage-vat-station"><button type="button" class="bb-vat vat-selector is-full" data-input="taskRaclageVat" data-allow-empty="true" aria-label="Vasca Piena. Tocca per cambiare." onclick="toggleTaskVat(this)"><span class="vat-fill"></span><strong>VASCA</strong><small>Linea ${esc(line)} · Raclage</small><span class="vat-state-label">Piena</span></button></div><input id="taskRaclageVat" type="hidden" value="full"><p class="raclage-estimate" id="taskRaclageEstimate">Quantità proposta: 3.000 pezzi</p><label class="field">Quantità precisa (facoltativa)<input id="taskRemaining" type="number" min="0" inputmode="numeric" placeholder="Lascia vuoto per usare la quantità proposta"></label><small class="muted">Se inserisci una quantità, sostituisce quella proposta.</small><button class="primary task-confirm" id="taskConfirm">Conferma e invia al CT</button>`;return `<strong>Linea ${esc(line)} · Verifica vasca vuota</strong><p>Controlla completamente la vasca e la linea durante lo scarico.</p><label class="task-clean"><input id="taskClean" type="checkbox"> Vasca e linea completamente pulite</label><button class="primary task-confirm" id="taskConfirm">Conferma vasca e linea pulite</button>`}
function showTaskDialog(line,kind){const old=$('#taskDialog');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='taskDialog';dialog.className='line-quick-dialog task-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button>${taskDialogContent(line,kind)}`;document.body.appendChild(dialog);if(kind==='raclage'){const l=appState.lines[line],level=l.raclageVatLevel;if(level){const vat=dialog.querySelector('.vat-selector');dialog.querySelector('#taskRaclageVat').value=level;vat.className=`bb-vat vat-selector is-${level}`;vat.querySelector('.vat-state-label').textContent=vatLabel(level);updateRaclageEstimate(dialog,level)}if(Number(l.remainingPieces)>=0&&Number(l.remainingPieces)!==raclageEstimate(level))dialog.querySelector('#taskRemaining').value=l.remainingPieces}dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.querySelector('#taskConfirm').onclick=async()=>{selected=line;let ok=false;if(kind==='pre'){const vatLevel=dialog.querySelector('#taskVat').value;if(!vatLevel)return toast('Tocca la vasca: piena, metà o quasi vuota',true);ok=await act('submit-pre',{bag1:dialog.querySelector('#taskBag1').value,bag2:dialog.querySelector('#taskBag2').value,vatLevel})}if(kind==='raclage'){const precise=dialog.querySelector('#taskRemaining').value,raclageVatLevel=dialog.querySelector('#taskRaclageVat').value;if(!raclageVatLevel)return toast('Tocca la vasca: piena, metà, quasi vuota o vuota',true);const value=precise===''?raclageEstimate(raclageVatLevel):precise;ok=await act('submit-raclage',{remainingPieces:value,raclageVatLevel})}if(kind==='unload'){if(!dialog.querySelector('#taskClean').checked)return toast('Conferma che vasca e linea siano completamente pulite',true);ok=await act('confirm-clean')}if(ok)dialog.close()};dialog.onclose=()=>dialog.remove();dialog.showModal()}
async function takeLineTask(line,kind){selected=line;const action=kind==='pre'?'take-pre':kind==='raclage'?'take-raclage':'take-unload';if(await act(action))showTaskDialog(line,kind)}
function lineCardAction(l){if(!canOperateLine(l))return'';const canComplete=l.assignedTo&&(l.assignedTo===actor()||isCT());if(l.stage==='pre'&&!l.assignedTo)return `<button class="line-card-action" data-line-task="pre">Prendo in carico</button>`;if(l.stage==='progress'&&l.remainingPieces===null&&canComplete)return `<button class="line-card-action" data-line-dialog="pre">Rispondi big bag</button>`;if(l.stage==='raclage'&&!l.assignedTo)return `<button class="line-card-action" data-line-task="raclage">Prendo in carico</button>`;if(l.stage==='progress'&&l.remainingPieces===-1&&canComplete)return `<button class="line-card-action" data-line-dialog="raclage">Inserisci pezzi avanzati</button>`;if(l.stage==='waiting-ct'&&canComplete)return `<button class="line-card-action" data-line-dialog="raclage">Modifica risposta raclage</button>`;if(l.stage==='raclage-ok'&&isCT())return `<button class="line-card-action" data-line-start-unload>Raclage finito · Avvia scarico</button>`;if(l.stage==='unload'&&!l.assignedTo)return `<button class="line-card-action" data-line-task="unload">Prendo in carico scarico</button>`;if(l.stage==='unload'&&canComplete)return `<button class="line-card-action" data-line-dialog="unload">Verifica vasca vuota</button>`;return''}
function bindLineGestures(){document.querySelectorAll('.line').forEach(button=>{const line=button.dataset.line;button.querySelectorAll('[data-line-task]').forEach(action=>action.onclick=event=>{event.preventDefault();event.stopPropagation();takeLineTask(line,action.dataset.lineTask)});button.querySelectorAll('[data-line-dialog]').forEach(action=>action.onclick=event=>{event.preventDefault();event.stopPropagation();selected=line;showTaskDialog(line,action.dataset.lineDialog)});button.querySelectorAll('[data-line-start-unload]').forEach(action=>action.onclick=event=>{event.preventDefault();event.stopPropagation();selected=line;act('start-unload')});button.onclick=event=>{if(event.target.closest('[data-line-task],[data-line-dialog],[data-line-start-unload]'))return;event.preventDefault();if(isCT())showLineActionMenu(line);else{selected=line;render()}}})}
function bindProductionSelector(){const choice=$('#productionLineSelect');if(choice)choice.onchange=()=>{const detail=choice.closest('#lineDetailDialog');selected=choice.value;if(detail)detail.close();render();if(detail)setTimeout(()=>showLineDetailsDialog(selected),30)}}
function openArea(area){if(area==='logistics'&&!canViewLogistics())return toast('Area riservata a Logistica, Direttore e Amministratore',true);currentArea=area;if(area==='production'&&canUseCtBottomNav())ctBottomNavActive='home';render();window.scrollTo({top:0,behavior:'smooth'})}
function dedicatedActivityHtml(l){return l.activity.length?l.activity.map(e=>`<div class="event ${esc(displayActivityKind(e))}"><strong>${esc(e.text)}</strong><small>${esc(e.actor)} · ${showTime(e.at)}</small></div>`).join(''):'<p class="muted">Nessuna attività.</p>'}
function dashboardGroup(key,title,description,lines,tone){return `<article class="dashboard-card dashboard-${tone}" data-dashboard-group="${key}"><div class="dashboard-card-heading"><span class="dashboard-card-icon" aria-hidden="true">${lines.length?'!':'✓'}</span><div><strong>${esc(title)}</strong><small>${esc(description)}</small></div><b>${lines.length}</b></div><div class="dashboard-lines">${lines.length?lines.map(line=>`<button type="button" data-dashboard-line="${esc(line.name)}"><span>Linea ${esc(line.name)}</span><small>${esc(labels[line.stage]||line.stage)}${line.assignedTo?` · ${esc(line.assignedTo)}`:''}</small><b>Apri →</b></button>`).join(''):'<p>Nessuna voce da gestire.</p>'}</div></article>`}
function dashboardHtml(){const all=Object.values(appState.lines),active=all.filter(line=>line.bottle&& !['idle','finished'].includes(line.stage)),preRaclage=all.filter(line=>['pre','progress','waiting-raclage','raclage','waiting-ct'].includes(line.stage)),unloads=all.filter(line=>line.stage==='unload'&&!line.cleanConfirmed),unanswered=all.filter(line=>line.stage==='pre'||(line.stage==='progress'&&(line.remainingPieces===null||line.remainingPieces===-1))||(line.stage==='raclage'&&!line.assignedTo)||(line.stage==='unload'&&!line.cleanConfirmed)),anomalies=all.filter(line=>line.ctDecision==='no'&&!['idle','finished'].includes(line.stage));return `<section class="dedicated-page-card dashboard-page"><div class="dedicated-page-heading dashboard-heading"><div><small>Produzione Live</small><h2>Dashboard riepilogativa</h2><p>Situazione aggiornata in tempo reale. Tocca una linea per aprirla e gestirla.</p></div><span class="dashboard-live"><i></i> LIVE</span></div><div class="dashboard-grid">${dashboardGroup('active','Linee attive','Produzioni attualmente in corso',active,'active')}${dashboardGroup('waiting','Pre-raclage e raclage','Operazioni in corso o da verificare',preRaclage,'waiting')}${dashboardGroup('unload','Scarichi da controllare','Verifica vasca e linea pulite',unloads,'unload')}${dashboardGroup('unanswered','Richieste senza risposta','Azioni ancora in attesa dell’operatore',unanswered,'unanswered')}${dashboardGroup('anomalies','Anomalie aperte','Risposte rifiutate dal CT e non risolte',anomalies,'anomaly')}</div></section>`}
function bindDashboard(){document.querySelectorAll('[data-dashboard-line]').forEach(button=>button.onclick=()=>{selected=button.dataset.dashboardLine;showLineActionMenu(selected)})}
